const adminRoot=document.createElement('main');adminRoot.id='admin-view';adminRoot.hidden=true;document.querySelector('.footer').before(adminRoot);
const demoOrders=[
{id:'TD-026',name:'Nadia Putri',title:'PPT proposal kegiatan kampus',service:'PPT & Presentasi',status:'Perlu dicek',payment:'Belum ditagih',price:0,deadline:'10 Sep · 16.00',brief:'Desain 15 slide dari materi yang sudah disiapkan. Gaya bersih, biru, untuk presentasi organisasi.',result:'',notes:[]},
{id:'TD-025',name:'Raka Pratama',title:'Website portofolio fotografi',service:'Coding & Website',status:'Menunggu pembayaran',payment:'Perlu verifikasi',price:750000,deadline:'14 Sep · 18.00',brief:'Website portofolio dengan galeri, profil, dan kontak. Materi foto tersedia. Pembayaran penuh pada contoh ini.',result:'',notes:[]},
{id:'TD-024',name:'Alya Safitri',title:'Format laporan & daftar pustaka',service:'Dokumen & Penulisan',status:'Dikerjakan',payment:'Dibayar',price:125000,deadline:'09 Sep · 12.00',brief:'Rapikan format 25 halaman, daftar isi, dan sitasi dari draft milik pelanggan.',result:'',notes:[]},
{id:'TD-023',name:'Dimas Saputra',title:'Revisi desain slide presentasi',service:'PPT & Presentasi',status:'Revisi',payment:'Dibayar',price:180000,deadline:'09 Sep · 19.00',brief:'Sesuaikan warna diagram di slide 4 dan 7. Revisi pertama dari dua putaran.',result:'presentasi-v1.pptx',notes:[]},
{id:'TD-022',name:'Salsa Anindya',title:'Review kode latihan JavaScript',service:'Bantuan & Review Tugas',status:'Selesai',payment:'Dibayar',price:85000,deadline:'08 Sep · 10.00',brief:'Review dan penjelasan alur fungsi pada kode latihan pelanggan.',result:'review-javascript.pdf',notes:[]}
];
let adminTab='Ringkasan',adminQuery='',adminFilter='Semua';
const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function pill(s){return `<span class="status-pill ${s==='Dibayar'||s==='Selesai'?'success':s==='Revisi'||s==='Perlu verifikasi'?'warning':s==='Dikerjakan'?'blue':''}">${escapeHTML(s)}</span>`;}
function filteredOrders(){return demoOrders.filter(o=>(adminTab!=='Pembayaran'||o.price>0)&&(adminFilter==='Semua'||o.status===adminFilter)&&`${o.id} ${o.name} ${o.title}`.toLowerCase().includes(adminQuery.toLowerCase()));}
function adminRows(){return filteredOrders().map(o=>`<tr><td><span class="order-code">${o.id}</span><strong>${o.title}</strong><small>${o.service}</small></td><td><span class="customer-avatar">${o.name[0]}</span>${o.name}</td><td>${o.deadline}<small>WITA · contoh</small></td><td>${pill(adminTab==='Pembayaran'?o.payment:o.status)}</td><td>${o.price?rupiah(o.price):'Belum ditentukan'}</td><td><button class="row-open" data-detail="${o.id}" aria-label="Buka ${o.id}">↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty-message">Tidak ada pesanan yang cocok. Coba kata kunci atau status lain.</td></tr>';}
function renderAdmin(){const paid=demoOrders.filter(o=>o.payment==='Dibayar').reduce((n,o)=>n+o.price,0);const active=demoOrders.filter(o=>o.status!=='Selesai').length;adminRoot.innerHTML=`<aside class="admin-sidebar"><a class="brand" href="#beranda"><span class="brand-mark">t<span>↗</span></span><span>techrey<span class="brand-sub">DIGITAL</span></span></a><span class="sidebar-label">WORKSPACE</span><nav aria-label="Menu admin">${[['Ringkasan','◫'],['Pesanan','▤'],['Pembayaran','◈']].map(([tab,icon])=>`<button data-tab="${tab}" class="${adminTab===tab?'selected':''}"><span>${icon}</span>${tab}${tab==='Pesanan'?'<b>'+demoOrders.length+'</b>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sandbox-box"><b>Ruang coba admin</b><p>Semua nama dan transaksi adalah contoh. Perubahan hilang saat halaman dimuat ulang.</p></div><a href="#beranda">↗ Lihat website</a><div class="admin-person"><span>T</span><div><strong>Techrey</strong><small>Pemilik usaha · demo</small></div></div></div></aside><div class="admin-main"><header class="admin-topbar"><span>Workspace <i>/</i> <b>${adminTab}</b></span><span class="admin-mode">● MODE DEMO</span></header><div class="admin-content"><div class="admin-heading"><div><span class="eyebrow">TECHREY DIGITAL / CONTROL ROOM</span><h1>${adminTab==='Ringkasan'?'Selamat datang, Techrey.':adminTab==='Pesanan'?'Semua pesanan.':'Pembayaran QRIS.'}</h1><p>${adminTab==='Ringkasan'?'Yang perlu kamu tangani, ada di sini.':adminTab==='Pesanan'?'Buka pesanan untuk meninjau brief, membuat penawaran, dan mengirim hasil.':'Periksa transaksi masuk sebelum mengonfirmasi pembayaran pelanggan.'}</p></div><a href="#pesan" class="button">Coba formulir pelanggan ↗</a></div>${adminTab==='Ringkasan'?`<section class="admin-stats"><article class="stat-primary"><span>Pembayaran terverifikasi</span><strong>${rupiah(paid)}</strong><small>Akumulasi data contoh</small><span class="stat-symbol">↗</span></article><article><span>Pesanan aktif</span><strong>${active.toString().padStart(2,'0')}</strong><small>Termasuk revisi dan antrean</small></article><article><span>Perlu verifikasi</span><strong>${demoOrders.filter(o=>o.payment==='Perlu verifikasi').length.toString().padStart(2,'0')}</strong><small>Pembayaran QRIS</small></article><article><span>Revisi masuk</span><strong>${demoOrders.filter(o=>o.status==='Revisi').length.toString().padStart(2,'0')}</strong><small>Perlu ditindaklanjuti</small></article></section><section class="attention-banner"><span class="attention-icon">↗</span><div><strong>Mulai dari yang perlu perhatian.</strong><p>Tinjau brief baru dan verifikasi pembayaran sebelum memulai pengerjaan.</p></div><button class="button small" data-detail="TD-026">Tinjau brief baru ↗</button></section>`:''}<section class="admin-table-card"><div class="table-heading"><h2>${adminTab==='Pembayaran'?'Daftar tagihan':'Daftar pesanan'}</h2><span>${demoOrders.length} pesanan contoh</span></div><div class="table-controls"><input id="admin-search" aria-label="Cari pesanan" placeholder="Cari nama, proyek, atau nomor pesanan…" value="${escapeHTML(adminQuery)}"><select id="admin-filter" aria-label="Filter status">${['Semua','Perlu dicek','Menunggu persetujuan','Menunggu pembayaran','Antrean','Dikerjakan','Revisi','Hasil dikirim','Selesai'].map(s=>`<option${adminFilter===s?' selected':''}>${s}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>PROYEK</th><th>PELANGGAN</th><th>TENGGAT</th><th>${adminTab==='Pembayaran'?'PEMBAYARAN':'STATUS'}</th><th>NILAI</th><th></th></tr></thead><tbody id="admin-rows">${adminRows()}</tbody></table></div></section><p class="admin-disclaimer">Pratinjau antarmuka admin · belum menggunakan login, penyimpanan server, atau transaksi nyata.</p></div></div><dialog id="detail-dialog" class="detail-dialog"></dialog>`;
adminRoot.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{adminTab=b.dataset.tab;adminFilter='Semua';adminQuery='';renderAdmin();}));adminRoot.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.detail)));document.getElementById('admin-search').addEventListener('input',e=>{adminQuery=e.target.value;refreshRows();});document.getElementById('admin-filter').addEventListener('change',e=>{adminFilter=e.target.value;refreshRows();});}
function refreshRows(){document.getElementById('admin-rows').innerHTML=adminRows();document.querySelectorAll('#admin-rows [data-detail]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.detail)));}
function openDetail(id){const o=demoOrders.find(x=>x.id===id);const dialog=document.getElementById('detail-dialog');dialog.innerHTML=`<div class="detail-top"><span>${o.id} / DETAIL PESANAN</span><button id="close-detail" aria-label="Tutup detail">✕</button></div><div class="detail-body"><span class="eyebrow">${escapeHTML(o.service)}</span><h2>${escapeHTML(o.title)}</h2><p class="detail-customer">${escapeHTML(o.name)} · ${o.deadline} WITA</p><div class="detail-pills">${pill(o.status)} ${pill(o.payment)}</div><section class="detail-brief"><h3>Brief pelanggan</h3><p>${escapeHTML(o.brief)}</p></section><div id="detail-feedback" role="status"></div><form id="offer-form" class="detail-section"><h3>01 / Penawaran</h3><label for="offer-price">Harga penawaran (Rp)</label><input id="offer-price" type="number" min="1000" step="1000" required value="${o.price||''}" placeholder="Contoh: 150000" ${o.payment==='Dibayar'?'disabled':''}><label for="offer-scope">Hasil & ketentuan revisi</label><textarea id="offer-scope" required minlength="10" ${o.payment==='Dibayar'?'disabled':''}>${escapeHTML(o.scope||'Hasil sesuai brief, 2 putaran revisi dalam lingkup yang disepakati.')}</textarea><button class="button small" ${o.payment==='Dibayar'?'disabled':''}>Simpan penawaran demo ↗</button></form><section class="detail-section"><h3>02 / Pembayaran QRIS</h3><div class="payment-summary"><span>Nilai tagihan</span><b>${o.price?rupiah(o.price):'Belum ditentukan'}</b></div><p class="field-hint">${o.payment==='Perlu verifikasi'?'Contoh: pelanggan menandai sudah membayar. Pada sistem aktif, admin mencocokkan bukti dengan transaksi merchant.':'Pembayaran dilakukan setelah penawaran disetujui pelanggan.'}</p><button id="verify-demo" class="button secondary small" ${o.payment!=='Perlu verifikasi'?'disabled':''}>Simulasikan pembayaran cocok ✓</button></section><form id="progress-form" class="detail-section"><h3>03 / Pengerjaan & hasil</h3><label for="work-status">Status pekerjaan</label><select id="work-status">${['Perlu dicek','Menunggu persetujuan','Menunggu pembayaran','Antrean','Dikerjakan','Revisi','Hasil dikirim','Selesai'].map(s=>`<option${o.status===s?' selected':''}>${s}</option>`).join('')}</select><label for="result-file">Pilih hasil contoh (maks. 10 MB)</label><input id="result-file" type="file"><p class="field-hint">${o.result?'File contoh: '+escapeHTML(o.result):'Belum ada hasil.'} File hanya dipilih di perangkat, tidak diunggah.</p><button class="button small">Simpan perubahan demo ↗</button></form><section class="detail-section"><h3>Riwayat sesi ini</h3><ul class="activity-list">${o.notes.length?o.notes.map(n=>'<li>'+escapeHTML(n)+'</li>').join(''):'<li>Belum ada perubahan pada contoh pesanan ini.</li>'}</ul></section></div>`;dialog.showModal();document.getElementById('close-detail').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();},{once:true});
const update=message=>{o.notes.unshift(message);dialog.close();renderAdmin();openDetail(id);const fb=document.getElementById('detail-feedback');fb.className='admin-feedback';fb.textContent=message;};
document.getElementById('offer-form').onsubmit=e=>{e.preventDefault();if(o.payment==='Dibayar')return;o.price=Number(document.getElementById('offer-price').value);o.scope=document.getElementById('offer-scope').value;o.status='Menunggu persetujuan';o.payment='Belum ditagih';update('Penawaran disimpan pada demo. Tidak dikirim ke pelanggan.');};
document.getElementById('verify-demo').onclick=()=>{if(o.payment!=='Perlu verifikasi')return;o.payment='Dibayar';o.status='Antrean';update('Simulasi pembayaran terverifikasi. Pesanan masuk antrean.');};
document.getElementById('progress-form').onsubmit=e=>{e.preventDefault();const status=document.getElementById('work-status').value;const result=document.getElementById('result-file').files[0];const fb=document.getElementById('detail-feedback');function fail(m){fb.className='admin-feedback error-text';fb.textContent=m;fb.scrollIntoView({block:'center'});}if(['Antrean','Dikerjakan','Revisi','Hasil dikirim','Selesai'].includes(status)&&o.payment!=='Dibayar'){fail('Verifikasi pembayaran sebelum masuk tahap pengerjaan.');return;}if(result&&result.size>10*1024*1024){fail('File maksimal 10 MB.');return;}if(['Hasil dikirim','Selesai'].includes(status)&&!result&&!o.result){fail('Pilih file hasil contoh terlebih dahulu.');return;}if(result)o.result=result.name;o.status=status;update('Status dan hasil contoh diperbarui dalam sesi ini.');};}
function adminRoute(){const yes=location.hash==='#admin';adminRoot.hidden=!yes;document.body.classList.toggle('admin-active',yes);if(yes){home.hidden=true;order.hidden=true;renderAdmin();document.title='Admin — Techrey Digital';window.scrollTo(0,0);}}
window.addEventListener('hashchange',adminRoute);adminRoute();
